def _v(tier, field, name, mission, venue, crew, roles, checklist, debrief):
    return topic(
        tier, "Social adventure: %s" % name,
        desc_pub="SAMPLE ADVENTURE - %s:\n\nYOUR SOCIAL ADVENTURE - %s\n\nThe mission: %s\n\nWhere: %s\nCrew: %s\n\nAssign roles (everyone gets one):\n%s\n\nAdventure checklist:\n%s\n\nDebrief (ask these on the way home):\n%s\n\nRule zero: nobody gets left out, nobody gets teased for trying. Adventures are measured in stories told afterward."
        % (field.upper(), name.upper(), mission, venue, crew,
           "\n".join(" - " + r for r in roles),
           "\n".join("%d. [ ] %s" % (i + 1, c) for i, c in enumerate(checklist)),
           "\n".join("%d. %s" % (i + 1, d) for i, d in enumerate(debrief))),
        desc_sig="Signature expedition: %s - the crew venturing out together, the mission binding them, the stories becoming family currency. The Signature edition treats every completed adventure as an entry in the book of us." % name,
        how_pub="Check the venue and weather first, assign roles before you leave (roles prevent drifting), and run the debrief on the way home while the stories are fresh.",
        how_sig="The Signature way: take one group photo at the start and one at the end - the difference between them is the adventure.",
        keys=["Mission: %s" % mission,
              "Venue: %s. Crew: %s." % (venue, crew),
              "%d roles assigned, %d checklist items." % (len(roles), len(checklist)),
              "Debrief questions turn the day into memory."],
        demo=("check", {"code": ["ROLES = %r" % roles, "CHECK = %r" % checklist, "DEB = %r" % debrief],
                        "checks": [("roles_cover_crew", "len(ROLES) >= 3"),
                                   ("checklist_actionable", "len(CHECK) >= 4"),
                                   ("debrief_present", "len(DEB) >= 2"),
                                   ("mission_stated", "%r != ''" % mission)]}),
    )


